.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4674:
	.ascii	"additional-properties-schema-widened"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4674, 36

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4675,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4675,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4675:
	.ascii	"A schema-valued additionalProperties assertion constrains arbitrary object members, while SHACL Core closure can only reject unlisted direct predicates. Named properties remain constrained and the arbitrary-value schema is widened."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4675, 231

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4676,@object
