	.ascii	"annotation-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4676, 18

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4677,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4677,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4677:
	.ascii	"A schema title, description, comment, example, default, deprecation marker, or native documentation annotation has no exact validation meaning in the imported SHACL shape and is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4677, 186

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4678,@object
