.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4678:
	.ascii	"array-contains-validation-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4678, 33

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4679,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4679,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4679:
	.ascii	"Schema contains/minContains/maxContains assertions quantify matching array members; the imported SHACL property retains item and total-cardinality constraints but cannot express that independent match count exactly."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4679, 215

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4680,@object
