.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4680:
	.ascii	"boolean-schema-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4680, 22

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4681,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4681,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4681:
	.ascii	"A standalone true or false schema has no class-targeted SHACL shape identity. The definition is omitted rather than inventing a caller vocabulary term."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4681, 151

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4682,@object
