	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4703,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4703:
	.ascii	"A schema logical applicator cannot be lowered to an equivalent finite SHACL and/or/xone/not shape at its position. Independently representable constraints remain and the applicator is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4703, 192

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4704,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4704,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4704:
