	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4704, 23

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4705,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4705,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4705:
	.ascii	"A schema document identifier, anchor, dialect declaration, generated package identity, or native module identity is not a SHACL vocabulary term. Caller-owned class and property IRIs remain; the carrier identity is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4705, 222

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4706,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4706,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4706:
	.ascii	"tuple-validation-widened"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4706, 24

