	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4707,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4707:
	.ascii	"Position-specific prefixItems/additionalItems or an equivalent tuple type has no direct RDF multi-value ordering contract on one predicate. Common item/cardinality constraints remain and positional validation is widened."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4707, 220

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4708,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4708,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4708:
	.ascii	"unevaluated-validation-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4708, 30

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4709,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4709,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4709:
	.ascii	"unevaluatedProperties/unevaluatedItems depends on schema-applicator evaluation state that SHACL Core does not expose. Local closure, named properties, and item constraints remain while the evaluation-state assertion is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4709, 227

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4710,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4710,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4710:
	.ascii	"unique-items-validation-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4710, 31

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4711,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4711,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4711:
	.ascii	"uniqueItems constrains duplicate JSON array members. RDF predicate values are a set in the data model, so the serialized-array assertion has no distinct imported SHACL constraint and is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4711, 194

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4712,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4712,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4712:
	.ascii	"unknown-keyword-dropped"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4712, 23

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4713,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4713,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4713:
	.ascii	"A valid extension or assertion outside the fixed importer capability table has no reviewed SHACL interpretation. It is omitted with a located entry rather than silently ignored or guessed."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4713, 188

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4714,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4714,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4714:
