	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4714, 23

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4715,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4715,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4715:
	.ascii	"The schema carrier admits values whose RDF term kind or exact datatype cannot be recovered uniquely. The importer retains the representable scalar/node carrier and records the unresolved term-kind distinction."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4715, 209

