	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4740,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4740:
	.ascii	"A frontmatter-less index.md navigation page has no OKF concept subject and is omitted from the RDF profile; its path is recorded on the runtime loss entry."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4740, 155

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4741,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4741,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4741:
	.ascii	"blob-bytes-absent"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4741, 17

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4742,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4742,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4742:
	.ascii	"Blob payloads are preserved as content-addressed references (the blob_id digest plus the origin file id), never materialized into the RDF IR, which must stay value-light for arbitrarily large payloads (e.g. multi-terabyte data dumps). A destination GTS carries the reference; the payload bytes are streamed origin->destination on demand (deferred materialization)."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4742, 364

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4743,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4743,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4743:
	.ascii	"lpg-annotation-sideband"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4743, 23

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4744,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4744,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4744:
	.ascii	"An RDF 1.2 statement annotation has no native property-graph semantics. Its exact term, predicate, object, and graph remain in the canonical RDF sideband for reversal."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4744, 167

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4745,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4745,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4745:
	.ascii	"lpg-blank-scope-sideband"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4745, 24

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4746,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4746,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4746:
	.ascii	"A blank node's RDF label scope has no native property-graph equivalent. Exact label and scope remain in the canonical RDF identity sideband."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4746, 140

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4747,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4747,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4747:
	.ascii	"lpg-edge-semantics-lowered"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4747, 26

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4748,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4748,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4748:
	.ascii	"An RDF predicate/object statement is lowered to an LPG edge or property. Full RDF term identity remains in sideband, but an LPG consumer does not inherit RDF semantics."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4748, 168

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4749,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4749,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4749:
	.ascii	"lpg-literal-semantics-lowered"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4749, 29

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4750,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4750,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4750:
	.ascii	"An RDF literal is lowered to an LPG property value. Lexical form, datatype, language, and RDF 1.2 base direction remain in sideband for exact reversal."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4750, 151

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4751,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4751,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4751:
