	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4751, 24

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4752,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4752,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4752:
	.ascii	"Property graphs have no RDF named-graph slot. Exact graph placement remains in sideband but is invisible to native LPG graph semantics."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4752, 135

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4753,@object
