	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4753, 20

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4754,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4754,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4754:
	.ascii	"An RDF 1.2 reifier binding has no native property-graph construct. It remains in canonical structural sideband for exact reversal."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4754, 130

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4755,@object
