	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4785, 11

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4786,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4786,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4786:
	.ascii	"A SHACL sh:disjoint constraint keeps the values apart from the nodes a property path (an IRI or any other SHACL 1.2 path) reaches from the focus node; JSON Schema constrains each property on its own and cannot relate one property's values to another path's, so the constraint is dropped."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4786, 287

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4787,@object
