	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4864,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4864,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4864:
	.ascii	"A property shape whose path is not one predicate (an inverse, sequence, alternative or closure path) constrains no outgoing JSON property of the projected node, so the property shape is dropped."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4864, 194

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4865,@object
