	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4868,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4868,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4868:
	.ascii	"A SHACL 1.2 sh:reifierShape constraint judges the reifiers of each value's triple, which the projected value does not carry, so the constraint is dropped."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4868, 154

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4869,@object
