	.ascii	"sh:reificationRequired"
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4869, 22

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4870,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4870,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4870:
	.ascii	"A SHACL 1.2 sh:reificationRequired true constraint requires each value's triple to be reified, which the projected value does not state, so the constraint is dropped."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4870, 166

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4871,@object
