	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4987,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4987:
	.ascii	"An RDF 1.2 reifier binding outside an exact OBO axiom-metadata mapping has no OBO Graphs representation and is omitted."
	.size	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4987, 119

	.type	.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4988,@object
	.section	.rodata..Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4988,"a",@progbits
.Lanon.bfd4107bfde1ba8247e7036a4c472cd7.4988:
